import 'client.dart';
class FlutterFeatureFlagSDK { final FenlengFlutterClient client; final Duration maxAge; Map<String,dynamic>? _flags; Set<String> _kills={}; DateTime? _fetchedAt; FlutterFeatureFlagSDK({required this.client,this.maxAge=const Duration(seconds:30)}); Future<void> refresh()async{final value=await client.request('/api/platform/v1/feature-flags');_flags=(value['flags'] as Map?)?.cast<String,dynamic>()??{};_kills=((value['killSwitches'] as List?)??[]).cast<String>().toSet();_fetchedAt=DateTime.now().toUtc();} ({bool value,bool stale,bool killed}) evaluate(String key,{bool defaultValue=false,bool highRisk=false}){final stale=_fetchedAt==null||DateTime.now().toUtc().difference(_fetchedAt!)>maxAge,killed=_kills.contains(key);final configured=_flags?[key] as Map?;return(value:killed?false:stale&&highRisk?false:configured?['enabled'] as bool? ?? defaultValue,stale:stale,killed:killed);} }
